mod math_ext {
  pub fn prime_factors(n: Int) -> Vec[Int] {
    let mut factors: Vec[Int] = Vec[Int].new();
    let mut num = n;
    let mut d = 2;
    while d * d <= num {
      while num % d == 0 {
        factors.push(d);
        num = num / d;
      };
      d += 1;
    };
    if num > 1 {
      factors.push(num);
    };
    factors
  }

  pub fn is_perfect(n: Int) -> Bool {
    if n <= 1 { return false; };
    let mut sum = 0;
    let mut i = 1;
    while i < n {
      if n % i == 0 {
        sum += i;
      };
      i += 1;
    };
    sum == n
  }

  pub fn digit_sum(n: Int) -> Int {
    let mut total = 0;
    let mut num = n;
    while num > 0 {
      total += num % 10;
      num = num / 10;
    };
    total
  }

  pub fn is_armstrong(n: Int) -> Bool {
    let digits = digit_count(n);
    let mut sum = 0;
    let mut num = n;
    while num > 0 {
      let d = num % 10;
      sum += power(d, digits);
      num = num / 10;
    };
    sum == n
  }

  fn digit_count(n: Int) -> Int { ... }
  fn power(base: Int, exp: Int) -> Int { ... }
}
```

### Key Patterns

- **Prime factors**: Repeatedly divide by smallest divisor
- **Perfect number**: Sum of proper divisors equals the number
- **Digit sum**: Extract each digit using modulo 10
- **Armstrong number**: Each digit raised to the power of digit count sums to the number

