use xiom.io;
module math_ext {
  pub fn count_digits(n: Int) -> Int {
    if n == 0 { return 1; };
    var count = 0;
    var num = n;
    while num > 0 {
      count += 1;
      num = num / 10;
    };
    count
  }

  pub fn reverse_number(n: Int) -> Int {
    var result = 0;
    var num = n;
    while num > 0 {
      result = result * 10 + (num % 10);
      num = num / 10;
    };
    result
  }

  pub fn sum_of_squares(n: Int) -> Int {
    var total = 0;
    var i = 1;
    while i <= n {
      total += i * i;
      i += 1;
    };
    total
  }
}

fn main() -> Int {
  io.println(math_ext.count_digits(12345).to_str());
  io.println(math_ext.reverse_number(1234).to_str());
  io.println(math_ext.sum_of_squares(5).to_str());
  return 0;
}
